from jsonb_to_recordset($q$[{"id": 11447, "materia": "ling", "nivel": 0, "enunciado": "Num cartaz da campanha de vacinação: \"Vacine-se! Proteja quem você ama.\" A função da linguagem que predomina é a:", "opcoes": ["Apelativa (conativa)", "Referencial", "Metalinguística", "Fática"], "explicacao": "O texto tenta convencer o leitor a agir, com verbos no imperativo."}, {"id": 11448, "materia": "ling", "nivel": 0, "enunciado": "No manual de instruções de um liquidificador, predomina o tipo de texto:", "opcoes": ["Injuntivo", "Narrativo", "Poético", "Argumentativo"], "explicacao": "Texto injuntivo orienta o leitor sobre como fazer algo."}, {"id": 11449, "materia": "ling", "nivel": 0, "enunciado": "Em inglês, a palavra \"library\" significa:", "opcoes": ["Biblioteca", "Livraria", "Liberdade", "Livro"], "explicacao": "É um falso cognato: livraria em inglês é bookstore."}, {"id": 11450, "materia": "ling", "nivel": 1, "enunciado": "Numa porta de loja nos Estados Unidos está escrito \"PUSH\". Isso significa:", "opcoes": ["Empurre", "Puxe", "Pare", "Entre devagar"], "explicacao": "Puxe, em inglês, é pull."}, {"id": 11451, "materia": "ling", "nivel": 1, "enunciado": "Uma charge publicada num jornal usa o humor, principalmente, para:", "opcoes": ["Criticar fatos sociais e políticos", "Ensinar regras gramaticais aos leitores", "Vender produtos", "Narrar contos de fadas"], "explicacao": "A charge comenta, com ironia, acontecimentos atuais."}, {"id": 11452, "materia": "ling", "nivel": 1, "enunciado": "Em \"Choveu canivetes ontem à noite\", há:", "opcoes": ["Hipérbole", "Eufemismo", "Antítese", "Ironia"], "explicacao": "Exagero intencional para enfatizar a força da chuva."}, {"id": 11453, "materia": "ling", "nivel": 2, "enunciado": "Um poema que fala sobre o próprio ato de escrever poemas usa, principalmente, a função:", "opcoes": ["Metalinguística", "Apelativa", "Referencial", "Fática"], "explicacao": "Metalinguagem é a linguagem falando de si mesma."}, {"id": 11454, "materia": "ling", "nivel": 2, "enunciado": "Numa conversa entre amigos no interior, alguém diz \"nóis vai na feira\". Do ponto de vista linguístico, isso é:", "opcoes": ["Variação linguística, adequada ao seu contexto", "Prova de que a pessoa não sabe falar português", "Uso da norma-padrão escrita", "Erro que deve ser ridicularizado"], "explicacao": "O Enem valoriza o respeito às variedades linguísticas e combate o preconceito linguístico."}, {"id": 11455, "materia": "ling", "nivel": 2, "enunciado": "A Semana de Arte Moderna de 1922 defendia:", "opcoes": ["Liberdade formal e valorização da cultura brasileira", "A volta das formas clássicas europeias do Parnasianismo", "Proibição de temas nacionais na arte", "O fim da poesia escrita"], "explicacao": "Os modernistas romperam com o academicismo."}, {"id": 11456, "materia": "ling", "nivel": 3, "enunciado": "Em Vidas Secas, de Graciliano Ramos, o tema central é:", "opcoes": ["A seca e a miséria de uma família de retirantes", "A vida da elite carioca no Segundo Reinado", "Uma viagem espacial futurista", "O amor romântico entre nobres"], "explicacao": "Romance da segunda fase modernista (1938), de forte denúncia social."}, {"id": 11457, "materia": "ling", "nivel": 3, "enunciado": "O Romantismo indianista, como em José de Alencar, idealizou o indígena como:", "opcoes": ["Herói nacional", "Inimigo da pátria", "Personagem cômico", "Símbolo do progresso industrial"], "explicacao": "Buscava-se criar uma identidade nacional após a Independência."}, {"id": 11458, "materia": "ling", "nivel": 3, "enunciado": "Quando um texto retoma outro, como uma propaganda que parodia um poema famoso, ocorre:", "opcoes": ["Intertextualidade", "Ambiguidade", "Redundância", "Neologismo"], "explicacao": "É o diálogo entre textos."}, {"id": 11459, "materia": "ling", "nivel": 4, "enunciado": "A literatura barroca se caracteriza, entre outros aspectos, por:", "opcoes": ["Contrastes e conflito entre fé e prazer", "Linguagem simples e cotidiana", "Valorização da máquina, da velocidade e da indústria", "Rejeição total da religiosidade"], "explicacao": "Uso de antíteses e paradoxos, como em Gregório de Matos."}, {"id": 11460, "materia": "ling", "nivel": 4, "enunciado": "Em \"Although it was raining, they went to the beach\", a palavra \"although\" expressa:", "opcoes": ["Concessão", "Causa", "Finalidade", "Tempo"], "explicacao": "Although = embora."}, {"id": 11461, "materia": "ling", "nivel": 4, "enunciado": "Em Dom Casmurro, de Machado de Assis, a dúvida sobre a traição de Capitu se sustenta porque:", "opcoes": ["A história é contada só pelo ponto de vista de Bentinho", "O narrador é imparcial e onisciente em terceira pessoa", "Capitu narra a própria história", "O livro apresenta provas de DNA"], "explicacao": "O narrador em primeira pessoa não é confiável."}, {"id": 11462, "materia": "mat", "nivel": 0, "enunciado": "Uma camiseta de R$ 40 está com 10% de desconto. Ela sai por:", "opcoes": ["R$ 36", "R$ 30", "R$ 34", "R$ 44"], "explicacao": "10% de 40 = 4; 40 − 4 = 36."}, {"id": 11463, "materia": "mat", "nivel": 0, "enunciado": "Um ônibus tem 40 lugares, e 32 estão ocupados. A fração ocupada é:", "opcoes": ["4/5", "3/4", "2/3", "8/40 apenas"], "explicacao": "32/40 = 4/5."}, {"id": 11464, "materia": "mat", "nivel": 0, "enunciado": "A área de um quarto retangular de 3 m por 4 m é:", "opcoes": ["12 m²", "7 m²", "14 m²", "24 m²"], "explicacao": "3 × 4 = 12."}, {"id": 11465, "materia": "mat", "nivel": 0, "enunciado": "Uma receita de bolo usa 2 xícaras de farinha. Para fazer 3 bolos, são necessárias:", "opcoes": ["6 xícaras", "5 xícaras", "4 xícaras", "8 xícaras"], "explicacao": "2 × 3 = 6."}, {"id": 11466, "materia": "mat", "nivel": 1, "enunciado": "Um time marcou 2, 1, 3 e 2 gols em quatro jogos. A média de gols por jogo foi:", "opcoes": ["2", "3", "8", "1,5"], "explicacao": "8 ÷ 4 = 2."}, {"id": 11467, "materia": "mat", "nivel": 1, "enunciado": "O perímetro de um terreno quadrado com 5 m de lado é:", "opcoes": ["20 m", "25 m", "10 m", "15 m"], "explicacao": "4 × 5 = 20."}, {"id": 11468, "materia": "mat", "nivel": 1, "enunciado": "A conta de luz subiu de R$ 100 para R$ 120. O aumento foi de:", "opcoes": ["20%", "12%", "120%", "2%"], "explicacao": "20 ÷ 100 = 20%."}, {"id": 11469, "materia": "mat", "nivel": 1, "enunciado": "Uma caixa tem 2 m de largura, 3 m de comprimento e 4 m de altura. Seu volume é:", "opcoes": ["24 m³", "9 m³", "12 m³", "20 m³"], "explicacao": "2 × 3 × 4 = 24."}, {"id": 11470, "materia": "mat", "nivel": 2, "enunciado": "Numa planta baixa feita na escala 1:50, uma sala aparece com 8 cm de comprimento. O comprimento real é:", "opcoes": ["4 m", "40 cm", "8 m", "50 cm"], "explicacao": "8 × 50 = 400 cm = 4 m."}, {"id": 11471, "materia": "mat", "nivel": 2, "enunciado": "Um plano de celular custa R$ 30 por mês, mais R$ 0,50 por minuto que passar da franquia. Com 40 minutos a mais, a conta será de:", "opcoes": ["R$ 50", "R$ 70", "R$ 30,50", "R$ 20"], "explicacao": "30 + 0,50 × 40 = 50."}, {"id": 11472, "materia": "mat", "nivel": 2, "enunciado": "Numa urna com bolas numeradas de 1 a 20, a probabilidade de sortear um múltiplo de 5 é:", "opcoes": ["1/5", "1/4", "1/20", "5/20 + 1"], "explicacao": "Múltiplos: 5, 10, 15, 20 = 4 em 20 = 1/5."}, {"id": 11473, "materia": "mat", "nivel": 4, "enunciado": "As vendas de uma loja foram 10, 20 e 40 unidades em três meses seguidos. Do segundo para o terceiro mês, o crescimento foi de:", "opcoes": ["100%", "20%", "50%", "200%"], "explicacao": "De 20 para 40: aumento de 20, que é 100% de 20."}, {"id": 11474, "materia": "mat", "nivel": 3, "enunciado": "Um terreno triangular tem 20 m de base e 15 m de altura. Sua área é:", "opcoes": ["150 m²", "300 m²", "35 m²", "75 m²"], "explicacao": "(base × altura) ÷ 2 = 300 ÷ 2."}, {"id": 11475, "materia": "mat", "nivel": 3, "enunciado": "R$ 500 rendem juros simples de 4% ao mês. Depois de 6 meses, o montante é:", "opcoes": ["R$ 620", "R$ 120", "R$ 524", "R$ 600"], "explicacao": "Juros: 500 × 0,04 × 6 = 120; montante: 620."}, {"id": 11476, "materia": "mat", "nivel": 3, "enunciado": "Uma rampa tem 3 m de altura e 4 m de base horizontal. O comprimento da rampa é:", "opcoes": ["5 m", "7 m", "6 m", "12 m"], "explicacao": "Teorema de Pitágoras: 3² + 4² = 25; √25 = 5."}, {"id": 11477, "materia": "mat", "nivel": 4, "enunciado": "A altura de uma bola é dada por h(t) = −5t² + 20t (em metros). A altura máxima é:", "opcoes": ["20 m", "40 m", "10 m", "5 m"], "explicacao": "O vértice ocorre em t = −20/(2 × −5) = 2; h(2) = −20 + 40 = 20."}, {"id": 11478, "materia": "mat", "nivel": 4, "enunciado": "Um carro perde 20% do valor a cada ano. Comprado por R$ 50.000, depois de 2 anos ele valerá:", "opcoes": ["R$ 32.000", "R$ 30.000", "R$ 40.000", "R$ 36.000"], "explicacao": "50.000 × 0,8 × 0,8 = 32.000."}, {"id": 11479, "materia": "mat", "nivel": 4, "enunciado": "Quantas senhas de 4 dígitos (de 0 a 9) podem ser criadas, permitindo repetição?", "opcoes": ["10.000", "5.040", "1.000", "40"], "explicacao": "10 × 10 × 10 × 10 = 10.000."}, {"id": 11480, "materia": "fis", "nivel": 0, "enunciado": "A energia elétrica consumida numa casa aparece na conta de luz medida em:", "opcoes": ["Quilowatt-hora (kWh)", "Newton (N)", "Metro por segundo (m/s)", "Grau Celsius (°C)"], "explicacao": "kWh mede energia consumida."}, {"id": 11481, "materia": "fis", "nivel": 0, "enunciado": "Um ciclista percorre 30 km em uma hora e meia. Sua velocidade média é:", "opcoes": ["20 km/h", "45 km/h", "30 km/h", "15 km/h"], "explicacao": "30 ÷ 1,5 = 20."}, {"id": 11482, "materia": "fis", "nivel": 1, "enunciado": "Quando o ônibus freia de repente, os passageiros são jogados para a frente por causa da:", "opcoes": ["Inércia", "Gravidade", "Pressão atmosférica", "Eletricidade"], "explicacao": "Primeira lei de Newton: os corpos tendem a manter o movimento."}, {"id": 11483, "materia": "fis", "nivel": 1, "enunciado": "A imagem de uma pessoa num espelho plano é:", "opcoes": ["Do mesmo tamanho, com esquerda e direita trocadas", "Maior, de cabeça para baixo e projetada na parede", "Menor e muito distante", "Invisível para quem olha"], "explicacao": "A imagem é virtual, direita e do mesmo tamanho, mas revertida."}, {"id": 11484, "materia": "fis", "nivel": 2, "enunciado": "Trocar uma lâmpada de 60 W por uma de LED de 9 W, ligada 5 horas por dia, economiza por dia:", "opcoes": ["0,255 kWh", "2,55 kWh", "0,045 kWh", "51 kWh"], "explicacao": "(60 − 9) W × 5 h = 255 Wh = 0,255 kWh."}, {"id": 11485, "materia": "fis", "nivel": 4, "enunciado": "No forno de micro-ondas, os alimentos esquentam porque as ondas:", "opcoes": ["Fazem as moléculas de água vibrar", "Queimam o alimento por fora com fogo", "Retiram o oxigênio da comida", "Transformam o alimento em metal"], "explicacao": "A agitação das moléculas gera calor."}, {"id": 11486, "materia": "fis", "nivel": 3, "enunciado": "Um elevador sobe com velocidade constante. A força resultante sobre ele é:", "opcoes": ["Nula", "Para cima e crescente", "Para baixo", "Igual ao peso dobrado"], "explicacao": "Velocidade constante significa aceleração zero (1ª lei de Newton)."}, {"id": 11487, "materia": "fis", "nivel": 3, "enunciado": "Ao descer numa piscina funda, o mergulhador sente mais pressão nos ouvidos porque:", "opcoes": ["A pressão da água aumenta com a profundidade", "A água fica mais quente e mais salgada no fundo", "O ar da piscina diminui", "A gravidade some debaixo d'água"], "explicacao": "A coluna de água acima dele fica maior."}, {"id": 11488, "materia": "fis", "nivel": 4, "enunciado": "Os painéis solares fotovoltaicos transformam:", "opcoes": ["Energia luminosa diretamente em elétrica", "Energia elétrica em luminosa durante a noite", "Energia química em térmica", "Energia nuclear em elétrica"], "explicacao": "Usam o efeito fotovoltaico."}, {"id": 11489, "materia": "fis", "nivel": 4, "enunciado": "No efeito estufa, gases como o CO₂ retêm o calor porque absorvem a radiação:", "opcoes": ["Infravermelha emitida pela Terra", "Ultravioleta refletida pela Lua", "Sonora dos ventos", "Gama das usinas"], "explicacao": "A Terra emite calor na forma de radiação infravermelha."}, {"id": 11490, "materia": "qui", "nivel": 0, "enunciado": "Quando o gelo derrete, ocorre a mudança de estado chamada:", "opcoes": ["Fusão", "Ebulição", "Condensação", "Sublimação"], "explicacao": "Passagem do sólido para o líquido."}, {"id": 11491, "materia": "qui", "nivel": 0, "enunciado": "A formação de ferrugem num portão de ferro é uma transformação:", "opcoes": ["Química", "Física", "Nuclear", "Mecânica"], "explicacao": "O ferro reage com oxigênio e água, formando nova substância."}, {"id": 11492, "materia": "qui", "nivel": 1, "enunciado": "O bicarbonato de sódio, usado para aliviar a azia, tem caráter:", "opcoes": ["Básico", "Ácido", "Neutro", "Radioativo"], "explicacao": "Uma base neutraliza o excesso de ácido no estômago."}, {"id": 11493, "materia": "qui", "nivel": 1, "enunciado": "O suco de limão, de sabor azedo, tem caráter:", "opcoes": ["Ácido", "Básico", "Neutro", "Salino"], "explicacao": "Contém ácido cítrico."}, {"id": 11494, "materia": "qui", "nivel": 2, "enunciado": "Para separar a areia misturada à água, pode-se usar a:", "opcoes": ["Filtração", "Destilação", "Evaporação apenas", "Fusão"], "explicacao": "O filtro retém a areia e deixa a água passar."}, {"id": 11495, "materia": "qui", "nivel": 2, "enunciado": "O gás mais abundante no ar atmosférico é o:", "opcoes": ["Nitrogênio", "Oxigênio", "Gás carbônico", "Hidrogênio"], "explicacao": "Cerca de 78% do ar; o oxigênio é cerca de 21%."}, {"id": 11496, "materia": "qui", "nivel": 3, "enunciado": "A combustão completa do etanol, usado como combustível, produz:", "opcoes": ["Gás carbônico e água", "Oxigênio e hidrogênio", "Sal e água", "Monóxido de carbono apenas"], "explicacao": "C₂H₆O + 3 O₂ → 2 CO₂ + 3 H₂O."}, {"id": 11497, "materia": "qui", "nivel": 3, "enunciado": "A chuva ácida é causada, principalmente, pela liberação de:", "opcoes": ["Óxidos de enxofre e de nitrogênio", "Oxigênio puro", "Vapor de água limpo", "Gás hélio"], "explicacao": "Esses óxidos reagem com a água da atmosfera formando ácidos."}, {"id": 11498, "materia": "qui", "nivel": 4, "enunciado": "Uma solução tem 10 g de açúcar por litro. Em 300 mL dela há:", "opcoes": ["3 g de açúcar", "30 g de açúcar", "0,3 g de açúcar", "10 g de açúcar"], "explicacao": "10 g/L × 0,3 L = 3 g."}, {"id": 11499, "materia": "qui", "nivel": 4, "enunciado": "O carbono-14 é usado para datar fósseis porque:", "opcoes": ["É radioativo e decai num ritmo conhecido", "Nunca se transforma", "Só existe em rochas vulcânicas muito antigas", "Brilha no escuro"], "explicacao": "Sua meia-vida é de cerca de 5.730 anos."}, {"id": 11500, "materia": "bio", "nivel": 0, "enunciado": "Os rins filtram o sangue e produzem a:", "opcoes": ["Urina", "Bile", "Saliva", "Insulina"], "explicacao": "A bile é produzida pelo fígado; a insulina, pelo pâncreas."}, {"id": 11501, "materia": "bio", "nivel": 0, "enunciado": "Nas plantas, a fotossíntese ocorre principalmente nas:", "opcoes": ["Folhas", "Raízes", "Sementes", "Flores secas"], "explicacao": "Os cloroplastos das folhas captam a luz."}, {"id": 11502, "materia": "bio", "nivel": 1, "enunciado": "A dengue é transmitida pela picada do mosquito:", "opcoes": ["Aedes aegypti", "Anopheles", "Barbeiro", "Mosca tsé-tsé"], "explicacao": "O mesmo mosquito transmite zika e chikungunya."}, {"id": 11503, "materia": "bio", "nivel": 1, "enunciado": "As vacinas protegem porque estimulam o organismo a:", "opcoes": ["Produzir anticorpos e células de memória", "Eliminar todos os glóbulos vermelhos do sangue", "Parar de produzir defesas", "Destruir os próprios órgãos"], "explicacao": "É a imunização ativa."}, {"id": 11504, "materia": "bio", "nivel": 2, "enunciado": "Nas células das plantas, a fotossíntese acontece numa organela chamada:", "opcoes": ["Cloroplasto", "Mitocôndria", "Núcleo", "Ribossomo"], "explicacao": "Contém clorofila, que capta a luz."}, {"id": 11505, "materia": "bio", "nivel": 2, "enunciado": "Numa cadeia alimentar, os produtores são:", "opcoes": ["Plantas e algas", "Leões e onças", "Fungos decompositores", "Herbívoros"], "explicacao": "Eles produzem o próprio alimento pela fotossíntese."}, {"id": 11506, "materia": "bio", "nivel": 2, "enunciado": "O bioma exclusivamente brasileiro, com vegetação adaptada à seca, é a:", "opcoes": ["Caatinga", "Amazônia", "Mata Atlântica", "Pampa"], "explicacao": "Plantas como o mandacaru armazenam água."}, {"id": 11507, "materia": "bio", "nivel": 3, "enunciado": "Pela teoria da seleção natural, de Darwin:", "opcoes": ["Os mais adaptados ao ambiente sobrevivem e se reproduzem mais", "Os animais mudam o corpo porque querem", "Todos os seres vivos são iguais desde sempre", "O uso constante de um órgão cria novas espécies na hora"], "explicacao": "A ideia de que o uso modifica o órgão é de Lamarck."}, {"id": 11508, "materia": "bio", "nivel": 3, "enunciado": "O uso de antibióticos sem necessidade é perigoso porque:", "opcoes": ["Seleciona bactérias resistentes", "Mata todos os vírus do corpo", "Cria novas vacinas", "Aumenta a imunidade para sempre"], "explicacao": "As bactérias sensíveis morrem, e as resistentes se multiplicam."}, {"id": 11509, "materia": "bio", "nivel": 1, "enunciado": "Nas enchentes, a leptospirose costuma se espalhar pela:", "opcoes": ["Urina de ratos misturada à água", "Picada de mosquitos durante a enchente", "Fumaça dos carros", "Luz do sol"], "explicacao": "Evitar contato com água de enchente é a principal prevenção."}, {"id": 11510, "materia": "bio", "nivel": 4, "enunciado": "No cruzamento Aa × Aa, com dominância completa, a proporção esperada de fenótipos é:", "opcoes": ["3 dominantes : 1 recessivo", "1 : 1", "1 : 2 : 1 nos fenótipos", "Todos dominantes"], "explicacao": "Genótipos 1 AA : 2 Aa : 1 aa; fenótipos 3 : 1."}, {"id": 11511, "materia": "bio", "nivel": 4, "enunciado": "A eutrofização de lagos ocorre por excesso de:", "opcoes": ["Nutrientes, como nitrogênio e fósforo", "Oxigênio dissolvido na água pelas plantas", "Peixes predadores", "Sal marinho"], "explicacao": "As algas proliferam, e a decomposição consome o oxigênio da água."}, {"id": 11512, "materia": "his", "nivel": 0, "enunciado": "Na Bahia, a Independência é comemorada no dia:", "opcoes": ["2 de Julho", "7 de Setembro", "15 de Novembro", "21 de Abril"], "explicacao": "Em 2 de julho de 1823, as tropas portuguesas deixaram Salvador."}, {"id": 11513, "materia": "his", "nivel": 0, "enunciado": "O Brasil foi colônia de qual país europeu?", "opcoes": ["Portugal", "Espanha", "França", "Holanda"], "explicacao": "De 1500 a 1822."}, {"id": 11514, "materia": "his", "nivel": 0, "enunciado": "Em Salvador, o Elevador Lacerda liga:", "opcoes": ["A Cidade Baixa à Cidade Alta", "A ilha de Itaparica ao continente", "O aeroporto à rodoviária", "A Bahia a Sergipe"], "explicacao": "Inaugurado em 1873, é um dos símbolos da cidade."}, {"id": 11515, "materia": "his", "nivel": 1, "enunciado": "A República foi proclamada no Brasil em:", "opcoes": ["1889", "1822", "1888", "1964"], "explicacao": "Em 15 de novembro de 1889."}, {"id": 11516, "materia": "his", "nivel": 1, "enunciado": "A Era Vargas começou com a:", "opcoes": ["Revolução de 1930", "Proclamação da República", "Independência do Brasil", "Abolição da escravidão"], "explicacao": "Getúlio Vargas governou de 1930 a 1945."}, {"id": 11517, "materia": "his", "nivel": 2, "enunciado": "A Sabinada (1837–1838) foi uma revolta que aconteceu na:", "opcoes": ["Bahia", "Amazônia", "Província do Rio Grande do Sul", "Província do Maranhão"], "explicacao": "Liderada por Francisco Sabino, em Salvador, durante o período regencial."}, {"id": 11518, "materia": "his", "nivel": 2, "enunciado": "A Guerra de Canudos (1896–1897), liderada por Antônio Conselheiro, aconteceu no sertão da:", "opcoes": ["Bahia", "Paraíba", "Amazônia", "Serra Gaúcha"], "explicacao": "Retratada por Euclides da Cunha em Os Sertões."}, {"id": 11519, "materia": "his", "nivel": 2, "enunciado": "A Inconfidência Mineira (1789) teve, entre suas causas, a cobrança da:", "opcoes": ["Derrama, imposto sobre o ouro", "Taxa sobre o café paulista", "Contribuição sobre a borracha", "Taxa sobre o petróleo"], "explicacao": "Tiradentes foi o integrante executado."}, {"id": 11520, "materia": "his", "nivel": 3, "enunciado": "O Ato Institucional nº 5 (AI-5), de 1968, ficou marcado por:", "opcoes": ["Fechar o Congresso e ampliar a censura e a repressão", "Garantir eleições diretas para presidente e governadores", "Encerrar a ditadura militar", "Criar a Constituição de 1988"], "explicacao": "Também suspendeu o habeas corpus para crimes políticos."}, {"id": 11521, "materia": "his", "nivel": 3, "enunciado": "A Primavera Árabe (2010–2012) foi:", "opcoes": ["Uma onda de protestos por democracia em países do norte da África e do Oriente Médio", "Um festival de música na Europa", "Um acordo de paz da Guerra Fria", "Uma crise econômica que atingiu só a América do Sul e o Caribe"], "explicacao": "Começou na Tunísia e se espalhou pela região."}, {"id": 11522, "materia": "his", "nivel": 3, "enunciado": "O Quilombo dos Palmares ficava na Serra da Barriga, no atual estado de:", "opcoes": ["Alagoas", "Bahia", "Minas Gerais", "Maranhão"], "explicacao": "Foi o maior quilombo do período colonial."}, {"id": 11523, "materia": "his", "nivel": 4, "enunciado": "A Revolta da Chibata, em 1910, foi liderada pelo marinheiro João Cândido contra:", "opcoes": ["Os castigos físicos na Marinha", "A vacinação obrigatória", "A cobrança de impostos sobre o ouro", "A proclamação da República"], "explicacao": "Os marinheiros, em sua maioria negros, eram punidos com chibatadas."}, {"id": 11524, "materia": "his", "nivel": 4, "enunciado": "A Lei dos Sexagenários, de 1885, libertava os escravizados:", "opcoes": ["Com mais de 60 anos", "Nascidos depois de 1871", "De todas as idades", "Que fugissem para quilombos no interior"], "explicacao": "Na prática, poucos chegavam a essa idade, e eles ainda deviam trabalhar alguns anos como indenização."}, {"id": 11525, "materia": "geo", "nivel": 0, "enunciado": "A rosa dos ventos é usada para indicar os:", "opcoes": ["Pontos cardeais", "Fusos horários", "Tipos de vento", "Climas do mundo"], "explicacao": "Norte, sul, leste e oeste."}, {"id": 11526, "materia": "geo", "nivel": 0, "enunciado": "O maior país da América do Sul em área é o:", "opcoes": ["Brasil", "Argentina", "Peru", "Colômbia"], "explicacao": "O Brasil ocupa quase metade do continente."}, {"id": 11527, "materia": "geo", "nivel": 1, "enunciado": "O clima predominante no sertão nordestino é o:", "opcoes": ["Semiárido", "Equatorial úmido", "Temperado", "Polar"], "explicacao": "Chuvas escassas e irregulares."}, {"id": 11528, "materia": "geo", "nivel": 1, "enunciado": "A cada 15° de longitude, o horário muda em:", "opcoes": ["1 hora", "15 minutos", "15 horas", "30 minutos"], "explicacao": "360° ÷ 24 h = 15° por hora."}, {"id": 11529, "materia": "geo", "nivel": 2, "enunciado": "O êxodo rural é a migração:", "opcoes": ["Do campo para a cidade", "Da cidade para o campo", "De um país para outro", "Do litoral para as ilhas"], "explicacao": "Muito intenso no Brasil entre 1950 e 1980."}, {"id": 11530, "materia": "geo", "nivel": 2, "enunciado": "Na Amazônia, grande parte do desmatamento está ligada principalmente à:", "opcoes": ["Pecuária e expansão agrícola", "Pesca artesanal", "Produção de energia solar", "Construção de praias artificiais"], "explicacao": "Áreas desmatadas viram pasto e lavoura."}, {"id": 11531, "materia": "geo", "nivel": 2, "enunciado": "As ilhas de calor urbanas acontecem porque, nas cidades:", "opcoes": ["Asfalto e concreto absorvem e retêm calor", "Há mais árvores e áreas verdes que no campo", "O ar é sempre mais limpo", "Chove todos os dias"], "explicacao": "A falta de vegetação também contribui."}, {"id": 11532, "materia": "geo", "nivel": 3, "enunciado": "A matriz elétrica brasileira se destaca por ter:", "opcoes": ["Grande participação de fontes renováveis", "Dependência quase total do carvão mineral importado", "Predomínio de usinas nucleares", "Nenhuma usina hidrelétrica"], "explicacao": "Hidrelétricas, eólicas e solares têm grande peso."}, {"id": 11533, "materia": "geo", "nivel": 3, "enunciado": "O principal objetivo da transposição do rio São Francisco é:", "opcoes": ["Levar água ao semiárido nordestino", "Gerar energia nuclear", "Abrir uma rota até o Pacífico", "Secar áreas alagadas da Amazônia para plantio"], "explicacao": "Canais levam água a regiões de seca."}, {"id": 11534, "materia": "geo", "nivel": 3, "enunciado": "Quando um bairro popular é valorizado e os antigos moradores são expulsos pelo aumento dos preços, ocorre:", "opcoes": ["Gentrificação", "Conurbação", "Metropolização", "Desertificação"], "explicacao": "Processo comum em centros históricos."}, {"id": 11535, "materia": "geo", "nivel": 4, "enunciado": "A queda da taxa de natalidade e o aumento da expectativa de vida no Brasil levam ao:", "opcoes": ["Envelhecimento da população", "Aumento do número de crianças", "Fim das migrações", "Crescimento da mortalidade infantil"], "explicacao": "É a transição demográfica."}, {"id": 11536, "materia": "geo", "nivel": 4, "enunciado": "Em geral, nos anos de El Niño, o Nordeste brasileiro tende a ter:", "opcoes": ["Secas mais intensas", "Neve no sertão", "Chuvas acima da média", "Furacões frequentes"], "explicacao": "O aquecimento do Pacífico altera a circulação atmosférica."}, {"id": 11537, "materia": "fil", "nivel": 0, "enunciado": "O filósofo que escreveu A República, descrevendo uma cidade ideal governada por filósofos, foi:", "opcoes": ["Platão", "Sócrates", "Nietzsche", "Maquiavel"], "explicacao": "Sócrates não deixou obras escritas."}, {"id": 11538, "materia": "fil", "nivel": 0, "enunciado": "A parte da Filosofia que estuda o comportamento moral, o certo e o errado, é a:", "opcoes": ["Ética", "Lógica", "Estética", "Metafísica"], "explicacao": "A estética estuda o belo; a lógica, o raciocínio correto."}, {"id": 11539, "materia": "fil", "nivel": 1, "enunciado": "No Mito da Caverna, Platão ilustra:", "opcoes": ["A passagem da ignorância para o conhecimento", "A criação do mundo pelos deuses do Olimpo", "A vida dos animais nas cavernas", "A origem da agricultura"], "explicacao": "As sombras representam as aparências."}, {"id": 11540, "materia": "fil", "nivel": 1, "enunciado": "Em O Príncipe, Maquiavel defende que o governante deve, acima de tudo:", "opcoes": ["Conquistar e manter o poder", "Seguir sempre a vontade da Igreja", "Abrir mão do poder", "Evitar qualquer decisão"], "explicacao": "Separou a política da moral religiosa."}, {"id": 11541, "materia": "fil", "nivel": 2, "enunciado": "Para Max Weber, a ação social é aquela:", "opcoes": ["Orientada pelo sentido que o indivíduo dá à ação dos outros", "Imposta somente pela natureza", "Que acontece sem nenhuma intenção ou sentido para quem age", "Feita só por governos"], "explicacao": "Weber classifica ações racionais, afetivas e tradicionais."}, {"id": 11542, "materia": "fil", "nivel": 2, "enunciado": "Para Karl Marx, a história é marcada pela luta de classes, no capitalismo entre:", "opcoes": ["Burguesia e proletariado", "Reis e rainhas", "Professores e alunos", "Cidade e campo apenas"], "explicacao": "A burguesia é dona dos meios de produção."}, {"id": 11543, "materia": "fil", "nivel": 3, "enunciado": "A frase \"Penso, logo existo\", de Descartes, é base do:", "opcoes": ["Racionalismo", "Empirismo", "Ceticismo absoluto", "Existencialismo"], "explicacao": "A razão é o ponto de partida do conhecimento seguro."}, {"id": 11544, "materia": "fil", "nivel": 3, "enunciado": "Para John Locke, o Estado existe para proteger direitos naturais como:", "opcoes": ["Vida, liberdade e propriedade", "Só o poder do rei", "Apenas a religião oficial", "Somente a guerra"], "explicacao": "Se o governo viola esses direitos, o povo pode resistir."}, {"id": 11545, "materia": "fil", "nivel": 4, "enunciado": "O imperativo categórico de Kant diz que devemos agir:", "opcoes": ["De modo que nossa regra possa valer para todos", "Sempre buscando o próprio prazer", "Conforme a vontade da maioria das pessoas", "Somente pelas consequências"], "explicacao": "A moral se funda na razão e no dever."}, {"id": 11546, "materia": "fil", "nivel": 4, "enunciado": "Para Zygmunt Bauman, a \"modernidade líquida\" se caracteriza por:", "opcoes": ["Relações frágeis, rápidas e instáveis", "Tradições rígidas que nunca mudam com o tempo", "Fim de toda tecnologia", "Vida apenas no campo"], "explicacao": "Laços humanos e identidades fluidas."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes where id < 1000000));
select nivel, count(*) as questoes_novas from public.questoes where id between 11447 and 11546 group by nivel order by nivel;
select public.questoes_versao() as nova_versao;
